using Microsoft.EntityFrameworkCore;using TechnifyERP.Application.CourseChanges;using TechnifyERP.Domain.Entities;using TechnifyERP.Domain.Enums;using TechnifyERP.Infrastructure.Fees;using TechnifyERP.Infrastructure.Persistence;
namespace TechnifyERP.Infrastructure.CourseChanges;
internal sealed class CourseChangeService(ApplicationDbContext db):ICourseChangeService
{ public async Task<IReadOnlyList<CourseChangeDto>> GetForStudentAsync(string s,CancellationToken ct=default)=>await GetAsync(db.CourseChangeRequests.Where(x=>x.StudentUserId==s),ct); public async Task<IReadOnlyList<CourseChangeDto>> GetAllAsync(CancellationToken ct=default)=>await GetAsync(db.CourseChangeRequests,ct);
 private async Task<IReadOnlyList<CourseChangeDto>> GetAsync(IQueryable<CourseChangeRequest> requests,CancellationToken ct){var rows=await requests.AsNoTracking().Include(x=>x.FromCourse).Include(x=>x.ToCourse).OrderByDescending(x=>x.RequestedAtUtc).ToListAsync(ct);var ids=rows.Select(x=>x.StudentUserId).Distinct().ToList();var users=await db.Users.AsNoTracking().Where(x=>ids.Contains(x.Id)).ToDictionaryAsync(x=>x.Id,ct);var profiles=await db.StudentProfiles.AsNoTracking().Where(x=>ids.Contains(x.UserId)).ToDictionaryAsync(x=>x.UserId,x=>x.RegistrationNumber,ct);return rows.Select(x=>new CourseChangeDto(x.Id,x.StudentUserId,users[x.StudentUserId].FullName,profiles.GetValueOrDefault(x.StudentUserId),x.FromCourseId,x.FromCourse.CourseCode,x.FromCourse.Name,x.FromCourse.MonthlyFee,x.ToCourseId,x.ToCourse.CourseCode,x.ToCourse.Name,x.ToCourse.MonthlyFee,x.Reason,x.Status,x.AdminRemarks,x.RequestedAtUtc)).ToList();}
 public async Task<CourseChangeActionResult>CreateAsync(string s,int from,int to,string reason,CancellationToken ct=default){if(from==to||string.IsNullOrWhiteSpace(reason))return CourseChangeActionResult.InvalidRequest;var enrolled=await db.CourseEnrollments.AnyAsync(x=>x.StudentUserId==s&&x.CourseId==from&&x.Status==EnrollmentStatus.Approved,ct);var target=await db.Courses.AnyAsync(x=>x.Id==to,ct);if(!enrolled||!target||await db.CourseEnrollments.AnyAsync(x=>x.StudentUserId==s&&x.CourseId==to,ct)||await db.CourseChangeRequests.AnyAsync(x=>x.StudentUserId==s&&x.Status==CourseChangeStatus.Pending,ct))return CourseChangeActionResult.InvalidRequest;db.Add(new CourseChangeRequest{StudentUserId=s,FromCourseId=from,ToCourseId=to,Reason=reason.Trim()});await db.SaveChangesAsync(ct);return CourseChangeActionResult.Success;}
 public async Task<CourseChangeActionResult>ReviewAsync(int id,bool approve,string? remarks,CancellationToken ct=default){var r=await db.CourseChangeRequests.FirstOrDefaultAsync(x=>x.Id==id,ct);if(r is null)return CourseChangeActionResult.NotFound;if(r.Status!=CourseChangeStatus.Pending)return CourseChangeActionResult.AlreadyReviewed;r.Status=approve?CourseChangeStatus.Approved:CourseChangeStatus.Rejected;r.AdminRemarks=remarks?.Trim();r.ReviewedAtUtc=DateTime.UtcNow;if(approve){var old=await db.CourseEnrollments.FirstOrDefaultAsync(x=>x.StudentUserId==r.StudentUserId&&x.CourseId==r.FromCourseId&&x.Status==EnrollmentStatus.Approved,ct);if(old is null)return CourseChangeActionResult.InvalidRequest;old.Status=EnrollmentStatus.Rejected;old.ReviewedAtUtc=DateTime.UtcNow;var next=new CourseEnrollment{StudentUserId=r.StudentUserId,CourseId=r.ToCourseId,Status=EnrollmentStatus.Approved,ReviewedAtUtc=DateTime.UtcNow};db.Add(next);await db.SaveChangesAsync(ct);var course=await db.Courses.FindAsync([r.ToCourseId],ct);db.FeeRecords.Add(FeeService.CreateRecord(next,DateTime.Today.Month,DateTime.Today.Year));}await db.SaveChangesAsync(ct);return CourseChangeActionResult.Success;}}
